    [InlineData(1, 0, 0)]
    [InlineData(0, 2, 2)]
    [InlineData(4, 0, 0)]
    [InlineData(1, 1, 2)]
    public void Dispense_valide_retire_les_billets(int f, int t, int d)
    {
        var m = new MoneyDispenser(new NoteCounts(5, 5, 5));
        Assert.True(m.Dispense(new NoteCounts(f, t, d)));
        Assert.Equal(new NoteCounts(5 - f, 5 - t, 5 - d), m.Stock);
    }

